        return parse_abbr(text, zone)
    if fmt == "epoch-jsonl":
        return parse_epoch(text)
    if fmt == "offset-csv":
        return parse_offset(text)
    if fmt == "legacy-fixed":
        return parse_legacy(text, zone)
    if fmt == "de-tsv":
        return parse_de(text, zone)
    if fmt == "local-csv":
        return parse_local_csv(text, zone)
    if fmt == "local-jsonl":
        return parse_local_jsonl(text, zone)
    raise ValueError("unknown format " + fmt)


def walk_files(root):
    found = []
    for base, _dirs, names in os.walk(root):
        for name in names:
            found.append(os.path.join(base, name))
    return sorted(found)


def parse_utc(text):
    return datetime.fromisoformat(text.strip().replace("Z", "+00:00")).astimezone(UTC)


def round_punch(stamp, zone):
    offset = int(datetime.fromtimestamp(stamp, UTC).astimezone(zone).utcoffset().total_seconds())
    local = stamp + offset
    return ((local + 180) // 360) * 360 - offset


def night_minutes(start, end, zone):
    first = datetime.fromtimestamp(start, UTC).astimezone(zone).date() - timedelta(days=1)
    last = datetime.fromtimestamp(end, UTC).astimezone(zone).date()
    total = 0
    day = first
    while day <= last:
        begin = local_to_epoch(datetime.combine(day, dtime(22, 0)), zone)
        finish = local_to_epoch(datetime.combine(day + timedelta(days=1), dtime(6, 0)), zone)
        overlap = min(end, finish) - max(start, begin)
        if overlap > 0:
            total += overlap
        day += timedelta(days=1)
    return total // 60


def main(input_dir, output_file):
    with open(os.path.join(input_dir, "period.json")) as handle:
        period = json.load(handle)
    start_day = date.fromisoformat(period["start"])
    end_day = date.fromisoformat(period["end"])
    cutoff = parse_utc(period["corrections_cutoff"])

    with open(os.path.join(input_dir, "sites.csv"), newline="", encoding="utf-8-sig") as handle:
        sites = {row["site"].strip(): row for row in csv.DictReader(handle)}
    zones = {name: ZoneInfo(row["timezone"].strip()) for name, row in sites.items()}
    with open(os.path.join(input_dir, "employees.csv"), newline="", encoding="utf-8-sig") as handle:
        employees = [{k: v.strip() for k, v in row.items()} for row in csv.DictReader(handle)]
    with open(os.path.join(input_dir, "rates.csv"), newline="", encoding="utf-8-sig") as handle:
        rates = {}
        for row in csv.DictReader(handle):
            rates.setdefault(row["employee_id"].strip(), []).append(
                (date.fromisoformat(row["effective_from"].strip()), Decimal(row["hourly_rate"].strip())))
    for lst in rates.values():
        lst.sort()
    home_zone = {emp["employee_id"]: zones[emp["home_site"]] for emp in employees}

    punches = {}
    ever = set()
    for site, row in sites.items():
        folder = os.path.join(input_dir, "exports", site)
        if not os.path.isdir(folder):
            continue
        for path in walk_files(folder):
            for pid, emp, direction, stamp in parse_site(row["format"].strip(), read_text(path), zones[site]):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = {"emp": emp.strip(), "dir": direction, "ts": stamp}

    corrections = []
    cdir = os.path.join(input_dir, "corrections")
    if os.path.isdir(cdir):
        for path in walk_files(cdir):
            reader = csv.DictReader(io.StringIO(read_text(path)))
            for row in reader:
                if not row.get("correction_id") or row["correction_id"] == "correction_id":
                    continue
                corrections.append({k: (v or "").strip() for k, v in row.items() if k})
    corrections = [c for c in corrections if parse_utc(c["issued_at"]) <= cutoff]
    corrections.sort(key=lambda c: (parse_utc(c["issued_at"]), c["correction_id"]))
    applied = 0
    for corr in corrections:
        key = (corr["site"], corr["punch_id"])
        action = corr["action"]
        if action == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches:
                punches[key]["ts"] = int(datetime.fromisoformat(corr["time"]).timestamp())
                applied += 1
        elif action == "add":
            if key not in ever and key[0] in sites:
                ever.add(key)
                punches[key] = {"emp": corr["employee"], "dir": corr["type"].upper(),
                                "ts": int(datetime.fromisoformat(corr["time"]).timestamp())}
                applied += 1

    known = {emp["employee_id"] for emp in employees}
    by_emp = {}
    for (site, pid), data in punches.items():
        if data["emp"] in known:
            by_emp.setdefault(data["emp"], []).append((data["ts"], 0 if data["dir"] == "OUT" else 1, site, pid, data))

    def workday(stamp, emp):
        return datetime.fromtimestamp(stamp, UTC).astimezone(home_zone[emp]).date()

    def in_period(day):
        return start_day <= day <= end_day

    stats = {emp["employee_id"]: {"shifts": 0, "paid": 0, "ot": 0, "night": 0, "pay": Fraction(0)}
             for emp in employees}
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}

    for emp, plist in by_emp.items():
        plist.sort(key=lambda p: p[:4])
        kept = []
        for stamp, order, site, pid, _data in plist:
            rounded = round_punch(stamp, zones[site])
            if kept and kept[-1]["order"] == order and stamp - kept[-1]["ts"] <= 300:
                if in_period(workday(rounded, emp)):
                    exc["duplicates_dropped"] += 1
                continue
            kept.append({"ts": stamp, "order": order, "site": site, "rts": rounded})
        shifts = []
        pending = None
        for punch in kept:
            if punch["order"] == 1:
                if pending is not None and in_period(workday(pending["rts"], emp)):
                    exc["open_shifts"] += 1
                pending = punch
            else:
                if pending is not None and punch["rts"] - pending["rts"] <= 16 * 3600:
                    shifts.append((pending, punch))
                    pending = None
                else:
                    if pending is not None:
                        if in_period(workday(pending["rts"], emp)):
                            exc["open_shifts"] += 1
                        pending = None
                    if in_period(workday(punch["rts"], emp)):
                        exc["orphan_outs"] += 1
        if pending is not None and in_period(workday(pending["rts"], emp)):
            exc["open_shifts"] += 1

        rows = []
        for pin, pout in shifts:
            day = workday(pin["rts"], emp)
            if not in_period(day):
                continue
            worked = max(0, (pout["rts"] - pin["rts"]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(pin["rts"], pout["rts"], zones[pin["site"]]), paid)
            rows.append({"day": day, "in": pin["rts"], "paid": paid, "night": night})
        rows.sort(key=lambda r: r["in"])
        day_total = {}
        for row in rows:
            before = day_total.get(row["day"], 0)
            row["daily"] = max(0, before + row["paid"] - max(before, 480))
            day_total[row["day"]] = before + row["paid"]
        week_total = {}
        for row in rows:
            week = row["day"] - timedelta(days=row["day"].weekday())
            base = row["paid"] - row["daily"]
            before = week_total.get(week, 0)
            weekly = max(0, before + base - max(before, 2400))
            week_total[week] = before + base
            overtime = row["daily"] + weekly
            regular = row["paid"] - overtime
            rate = Fraction(0)
            for effective, value in rates.get(emp, []):
                if effective <= row["day"]:
                    rate = Fraction(value)
            pay = rate * (regular + Fraction(3, 2) * overtime) / 60 + rate * Fraction(15, 100) * row["night"] / 60
            st = stats[emp]
            st["shifts"] += 1
            st["paid"] += row["paid"]
            st["ot"] += overtime
            st["night"] += row["night"]
            st["pay"] += pay

    def cents(value):
        return (value * 100 + Fraction(1, 2)).__floor__()

    def money(count):
        return "%d.%02d" % divmod(count, 100)

    result_emps = {}
    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    total_cents = 0
    for emp in employees:
        st = stats[emp["employee_id"]]
        gross = cents(st["pay"])
        result_emps[emp["employee_id"]] = {
            "shifts": st["shifts"], "paid_minutes": st["paid"], "overtime_minutes": st["ot"],
            "night_minutes": st["night"], "gross": money(gross)}
        totals["shifts"] += st["shifts"]
        totals["paid_minutes"] += st["paid"]
        totals["overtime_minutes"] += st["ot"]
        totals["night_minutes"] += st["night"]
        total_cents += gross
    totals["gross"] = money(total_cents)
    result = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": result_emps,
        "exceptions": dict(exc, corrections_applied=applied),
        "totals": totals,
    }
    with open(output_file, "w") as handle:
        json.dump(result, handle, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
